@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--bg:#101114;--panel:#17181d;--line:#2a2b31;--muted:#777a84;--white:#f1f0eb;--red:#ee4d4a;--blue:#52a6e8;--gold:#e4bd70}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--white);font-family:Manrope,Arial,sans-serif;min-height:100vh;background-image:radial-gradient(ellipse at 50% -30%,#27252b 0,transparent 58%)}button{font:inherit}.shell{max-width:1180px;margin:0 auto;padding:0 36px 26px}.topbar{height:74px;border-bottom:1px solid #ffffff12;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--white);font:800 17px 'Barlow Condensed',sans-serif;letter-spacing:1.6px}.brand-mark{width:26px;height:26px;border:1px solid var(--gold);color:var(--gold);display:grid;place-items:center;font-size:16px}.brand-light{font-weight:500;color:#999}.event,.sound-button{font:10px 'DM Mono',monospace;letter-spacing:1.2px;color:#a6a6aa}.event{display:flex;gap:10px;align-items:center}.live-dot{height:6px;width:6px;border-radius:50%;background:var(--red);box-shadow:0 0 10px #ee4d4a}.event-divider{color:#4d4e54}.sound-button{border:1px solid #37383d;background:transparent;color:#aaa;padding:9px 12px;display:flex;align-items:center;gap:8px;cursor:pointer}.sound-button:hover{border-color:var(--gold);color:var(--gold)}.sound-icon{font-size:15px}.fight-card{display:flex;justify-content:space-between;align-items:center;padding:22px 4px 19px}.fighter-head{display:flex;align-items:center;gap:30px;width:40%}.blue-head{justify-content:flex-end;text-align:right}.fighter-id h2{font:800 32px/.82 'Barlow Condensed',sans-serif;letter-spacing:.3px;margin:8px 0 7px}.fighter-id em{font-style:normal;color:var(--red)}.blue-head em{color:var(--blue)}.fighter-id p{font:9px 'DM Mono',monospace;color:#898b92;letter-spacing:1px;margin:0}.corner-tag,.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.5px;color:#aaa}.red-tag{color:var(--red)}.blue-tag{color:var(--blue)}.record{display:flex;flex-direction:column;align-items:center;border-left:1px solid #ffffff20;padding-left:17px}.blue-head .record{border-left:0;border-right:1px solid #ffffff20;padding-left:0;padding-right:17px}.record strong{font:700 21px 'Barlow Condensed',sans-serif}.record span{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#6f7078}.arena-wrap{border:1px solid #393a40;background:#111216;box-shadow:0 18px 55px #0005}.arena-topline,.arena-bottomline{height:31px;display:flex;align-items:center;justify-content:space-between;padding:0 14px;font:9px 'DM Mono',monospace;letter-spacing:1px;color:#85868c}.arena-topline{border-bottom:1px solid #ffffff10}.arena-bottomline{border-top:1px solid #ffffff12}.round-label{color:var(--gold)}.canvas-frame{height:390px;position:relative;overflow:hidden;background:#17171b}.canvas-frame canvas{width:100%;height:100%;display:block}.round-clock{position:absolute;top:15px;left:50%;transform:translateX(-50%);z-index:2;display:flex;align-items:center;gap:11px;background:#0c0d0fdb;border:1px solid #ffffff1a;padding:7px 12px}.clock-label{font:8px 'DM Mono',monospace;color:#8b8b91;letter-spacing:.8px}.round-clock strong{font:700 17px 'Barlow Condensed',sans-serif;min-width:30px;text-align:center}.clock-pips{display:flex;gap:3px}.clock-pips i{width:5px;height:5px;border-radius:50%;background:#51525a}.clock-pips i.active{background:var(--gold)}.callout{position:absolute;top:77px;left:50%;transform:translateX(-50%);z-index:2;font:800 22px 'Barlow Condensed',sans-serif;font-style:italic;letter-spacing:2px;color:var(--gold);text-shadow:0 2px 12px #000;opacity:0;transition:opacity .15s;white-space:nowrap}.callout.show{opacity:1}.center-message,.result-overlay{position:absolute;inset:0;z-index:3;display:grid;place-items:center;background:linear-gradient(90deg,#090a0dce,#111216a8 50%,#090a0dce)}.message-card{text-align:center;max-width:450px;padding:22px}.message-card h1{font:900 57px/.82 'Barlow Condensed',sans-serif;letter-spacing:1px;margin:13px 0}.message-card h1 em{font-style:normal;color:var(--gold)}.message-card p,.result-overlay p{font-size:11px;color:#aaa;letter-spacing:.3px;margin:12px 0 20px}.start-button{background:var(--gold);border:0;color:#171513;padding:13px 20px;font:800 11px 'DM Mono',monospace;letter-spacing:.8px;cursor:pointer;transition:transform .15s,background .15s}.start-button span{font-size:17px;margin-left:12px}.start-button:hover{transform:translateY(-2px);background:#f2d18a}.quick-hint{margin-top:16px;font:8px 'DM Mono',monospace;color:#999;letter-spacing:.6px}.quick-hint kbd{margin:0 3px}.result-overlay{text-align:center;align-content:center}.result-overlay h2{font:900 40px 'Barlow Condensed',sans-serif;margin:12px 0;color:var(--gold)}.hidden{display:none!important}.status-row{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:13px 0 22px}.status-box{background:#17181d;border:1px solid #292a30;padding:12px 15px}.status-title,.meter-label{display:flex;justify-content:space-between;align-items:center}.status-title{font:9px 'DM Mono',monospace;letter-spacing:1px;color:var(--red);margin-bottom:10px}.blue-status .status-title{color:var(--blue)}.status-title span+span{font-size:8px;color:#85858b}.meter-label{font:8px 'DM Mono',monospace;color:#777981;letter-spacing:.7px;margin:5px 0}.meter-label strong{font-weight:400;color:#ccc}.meter{height:5px;background:#2c2d33;overflow:hidden}.meter i{height:100%;width:100%;display:block;transition:width .18s}.health i{background:linear-gradient(90deg,#df4945,#f88673)}.blue-status .health i{background:linear-gradient(90deg,#3a80bf,#68c6e8)}.stamina i{background:var(--gold)}.stamina-label{margin-top:8px}.controls{border-top:1px solid #ffffff13;border-bottom:1px solid #ffffff13}.controls-heading{display:flex;justify-content:space-between;padding:11px 1px;border-bottom:1px solid #ffffff12;font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#82838a}.controls-heading span:last-child{color:#5d5e66}.control-columns{display:grid;grid-template-columns:1fr 1fr}.control-player{display:flex;gap:13px;padding:15px 9px;border-right:1px solid #ffffff12}.control-player:last-child{border:0;padding-left:20px}.player-number{font:800 23px 'Barlow Condensed',sans-serif}.red-text{color:var(--red)}.blue-text{color:var(--blue)}.control-info h3{margin:1px 0 10px;font:700 10px 'DM Mono',monospace;letter-spacing:1px}.key-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px 17px}.key-grid span{font:8px 'DM Mono',monospace;color:#95969c;white-space:nowrap;display:flex;align-items:center;gap:4px}.key-grid kbd,.quick-hint kbd{min-width:18px;height:18px;padding:0 4px;display:inline-grid;place-items:center;border:1px solid #44454b;border-bottom-width:2px;border-radius:2px;color:#dedee0;font:9px 'DM Mono',monospace}.tip{font:9px 'DM Mono',monospace;color:#8c8d93;padding:0 0 13px;margin:0;letter-spacing:.1px}.tip span{color:var(--gold);margin-right:9px}footer{display:flex;justify-content:space-between;color:#5f6068;font:8px 'DM Mono',monospace;letter-spacing:1px;padding-top:17px}footer i{font-style:normal;color:var(--gold);padding:0 3px}
@media(max-width:700px){.shell{padding:0 14px 20px}.topbar{height:59px}.event{font-size:8px;gap:6px}.sound-button{padding:7px}.sound-button #soundLabel{display:none}.fighter-head{gap:12px}.fighter-id h2{font-size:27px}.record{padding-left:9px}.blue-head .record{padding-right:9px}.canvas-frame{height:330px}.arena-bottomline{font-size:7px;padding:0 8px}.status-row{gap:7px}.status-box{padding:10px}.control-player{gap:8px;padding:12px 4px}.control-player:last-child{padding-left:9px}.key-grid{gap:7px 5px}.key-grid span{font-size:7px}.key-grid kbd{min-width:16px;height:16px}.tip{font-size:8px;line-height:1.6}.message-card h1{font-size:48px}.quick-hint{font-size:7px}}@media(max-width:430px){.event{display:none}.fighter-id p{font-size:7px}.fighter-id h2{font-size:24px}.canvas-frame{height:300px}.key-grid{grid-template-columns:1fr}.control-player{min-width:0}.controls-heading{font-size:8px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { timer: $('timer'), round: $('roundLabel'), overlay: $('centerMessage'), result: $('resultOverlay'), callout: $('callout') };
  const keys = new Set();
  let W = 0, H = 0, last = 0, running = false, phase = 'intro', phaseTime = 0, round = 1, seconds = 60, soundOn = true, audio;
  let redWins = 0, blueWins = 0, particles = [], shake = 0, callTimer = 0, totalTime = 0;
  const fighters = [];
  const createFighter = (name, side) => ({name, side, face: side === 'red' ? 1 : -1, x: side === 'red' ? .29 : .71, depth: side === 'red' ? .57 : .43, hp: 100, stamina: 100, stun: 0, attack: null, dodge: '', dodgeTime: 0, guard: false, hitFlash: 0, bob: 0, wins: 0, roundDamage: 0, movement: 0, actionLock: 0});
  fighters.push(createFighter('RED','red'), createFighter('BLUE','blue'));
  const config = {
    red: { left:'a', right:'d', slipL:'w', slipR:'s', guard:'f', roll:'g', jab:'j', hook:'k', upper:'l' },
    blue: { left:'arrowleft', right:'arrowright', slipL:'arrowup', slipR:'arrowdown', guard:'i', roll:'o', jab:'1', hook:'2', upper:'3' }
  };
  function resize(){const r=canvas.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0)}
  new ResizeObserver(resize).observe(canvas); resize();
  function keyName(e){return e.key.toLowerCase()}
  window.addEventListener('keydown',e=>{const k=keyName(e);if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!keys.has(k)){keys.add(k);onPress(k)} });
  window.addEventListener('keyup',e=>keys.delete(keyName(e)));
  window.addEventListener('blur',()=>keys.clear());
  $('startButton').onclick=()=>beginMatch(); $('rematchButton').onclick=()=>{redWins=blueWins=0;updateWins();beginMatch()};
  $('soundToggle').onclick=()=>{soundOn=!soundOn;$('soundLabel').textContent=soundOn?'SOUND ON':'SOUND OFF';$('soundToggle').style.color=soundOn?'#e4bd70':''};
  function onPress(k){
    if(k==='escape'&&running){running=false;phase='paused';ui.overlay.classList.remove('hidden');ui.overlay.querySelector('.eyebrow').textContent='PAUSED';ui.overlay.querySelector('h1').innerHTML='TAKE A<br><em>BREATHER.</em>';ui.overlay.querySelector('p').textContent='Press ENTER to get back in the fight.';$('startButton').textContent='BACK TO THE FIGHT →';return}
    if(k==='enter'&&phase==='paused'){running=true;phase='fight';ui.overlay.classList.add('hidden');last=performance.now();return}
    if(!running)return;
    for(const f of fighters){const c=config[f.side];if(k===c.jab)strike(f,'jab');if(k===c.hook)strike(f,'hook');if(k===c.upper)strike(f,'upper')}
  }
  function beginMatch(){for(const f of fighters){f.hp=100;f.stamina=100;f.stun=0;f.attack=null;f.dodge='';f.wins=0;f.roundDamage=0;f.actionLock=0}round=1;redWins=blueWins=0;updateWins();startRound()}
  function startRound(){seconds=60;for(const f of fighters){f.hp=100;f.stamina=100;f.stun=0;f.attack=null;f.dodge='';f.guard=false;f.x=f.side==='red'?.29:.71;f.depth=f.side==='red'?.57:.43;f.roundDamage=0;f.actionLock=0}ui.result.classList.add('hidden');ui.overlay.classList.add('hidden');running=true;phase='count';phaseTime=3;last=performance.now();}
  function strike(f,type){if(f.stun>0||f.actionLock>0||f.attack||phase!=='fight'||f.stamina< (type==='jab'?7:15))return;const data={jab:{wind:.14,active:.12,recover:.24,cost:7,damage:7,reach:.24,label:'JAB'},hook:{wind:.24,active:.14,recover:.38,cost:15,damage:13,reach:.20,label:'HOOK'},upper:{wind:.28,active:.12,recover:.43,cost:17,damage:16,reach:.17,label:'UPPERCUT'}}[type];f.stamina-=data.cost;f.attack={type,elapsed:0,hit:false,...data};f.dodge='';f.guard=false;}
  function soundHit(strong=false){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.setValueAtTime(strong?110:170,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(45,audio.currentTime+.12);gain.gain.setValueAtTime(.12,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.14);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.15)}catch{}}
  function showCall(text){ui.callout.textContent=text;ui.callout.classList.add('show');callTimer=.8}
  function attackUpdate(f,dt){if(!f.attack)return;const a=f.attack;a.elapsed+=dt;if(!a.hit&&a.elapsed>=a.wind&&a.elapsed<=a.wind+a.active){a.hit=true;const target=fighters[f.side==='red'?1:0];const dx=Math.abs(target.x-f.x);const reach=a.reach*(H/390);const depthOk=Math.abs(target.depth-f.depth)<.30;if(dx<reach+.06&&depthOk){resolveHit(f,target,a)}else if(Math.random()<.28)showCall('JUST OUT OF RANGE');}if(a.elapsed>a.wind+a.active+a.recover){f.attack=null;f.actionLock=.08}}
  function resolveHit(attacker,target,a){
    const kind=a.type, avoided=(kind==='hook'&&target.dodge==='roll')||((kind==='jab'||kind==='upper')&&target.dodge==='slip');
    if(avoided){target.stamina=Math.max(0,target.stamina-2);showCall(kind==='hook'?'ROLLED UNDER!':'SLIPPED!');spawnText(target.x*W,H*(.49-target.depth*.03),kind==='hook'?'ROLL':'SLIP',target.side);attacker.actionLock=.18;return}
    let damage=a.damage;let text=a.label+'!';
    if(target.guard){damage*=kind==='upper'?0.55:.30;target.stamina=Math.max(0,target.stamina-(kind==='hook'?11:7));text='BLOCKED';if(target.stamina<=0){target.stun=.38;target.guard=false}}
    else{target.stun=kind==='jab'?.22:.34;target.hitFlash=.18;target.x+=attacker.face*.018;}
    target.hp=Math.max(0,target.hp-damage);target.roundDamage+=damage;attacker.stamina=Math.min(100,attacker.stamina+2);shake=Math.max(shake,kind==='upper'?5:kind==='hook'?4:2);soundHit(kind!=='jab');showCall(text);spawnText(target.x*W,H*(.52-target.depth*.04),Math.round(damage)+'',target.side);updateBars();
    if(target.hp<=0){endRound(attacker.side==='red'?'red':'blue',true)}
  }
  function spawnText(x,y,text,side){particles.push({x,y,text,side,life:.8})}
  function update(dt){totalTime+=dt;if(callTimer>0){callTimer-=dt;if(callTimer<=0)ui.callout.classList.remove('show')}
    if(phase==='count'){phaseTime-=dt;if(phaseTime<=0){if(phaseTime>-dt){phase='fight';seconds=60;showCall('FIGHT!')}else phase='fight'}return}
    if(phase!=='fight')return;
    seconds-=dt;if(seconds<=0){seconds=0;endRound(fighters[0].hp===fighters[1].hp?null:fighters[0].hp>fighters[1].hp?'red':'blue',false);return}
    for(const f of fighters){const c=config[f.side],enemy=fighters[f.side==='red'?1:0];f.bob+=dt*7;f.stun=Math.max(0,f.stun-dt);f.hitFlash=Math.max(0,f.hitFlash-dt);f.actionLock=Math.max(0,f.actionLock-dt);f.dodgeTime=Math.max(0,f.dodgeTime-dt);if(f.dodgeTime<=0)f.dodge='';
      f.guard=keys.has(c.guard)&&f.stun<=0&&!f.attack;if(f.guard)f.stamina=Math.max(0,f.stamina-dt*9);else f.stamina=Math.min(100,f.stamina+dt*(f.attack?3:12));if(f.stamina<=0)f.guard=false;
      if(f.dodgeTime<=0&&f.stun<=0&&!f.attack){if(keys.has(c.slipL)){f.dodge='slip';f.dodgeTime=.18;f.actionLock=.18;f.x-=f.face*.018;f.stamina=Math.max(0,f.stamina-5)}else if(keys.has(c.slipR)){f.dodge='slip';f.dodgeTime=.18;f.actionLock=.18;f.x+=f.face*.018;f.stamina=Math.max(0,f.stamina-5)}else if(keys.has(c.roll)){f.dodge='roll';f.dodgeTime=.39;f.actionLock=.39;f.stamina=Math.max(0,f.stamina-12)}}
      f.movement=0;if(f.stun<=0&&!f.attack&&!f.dodge){const dir=(keys.has(c.right)?1:0)-(keys.has(c.left)?1:0);if(dir){f.x+=dir*dt*.36;f.movement=dir}}if(!f.attack&&!f.guard&&!f.dodge)f.depth+=( (f.side==='red'?.57:.43)-f.depth)*dt*1.6;
      f.x=Math.max(.10,Math.min(.90,f.x));attackUpdate(f,dt);
    }
    const dx=fighters[1].x-fighters[0].x;if(dx<.20){const push=(.20-dx)*.5;fighters[0].x-=push;fighters[1].x+=push}
    particles=particles.filter(p=>{p.life-=dt;p.y-=dt*22;return p.life>0});shake=Math.max(0,shake-dt*22);updateBars();
  }
  function endRound(winner,ko){if(phase!=='fight')return;running=false;phase='between';if(winner==='red')redWins++;if(winner==='blue')blueWins++;updateWins();const label=winner?`${winner==='red'?'RED':'BLUE'} CORNER TAKES ROUND ${round}`:'ROUND '+round+' IS A DRAW';showCall(ko?'KNOCKDOWN!':'BELL!');
    if(redWins>=2||blueWins>=2||round>=3){phase='result';ui.result.classList.remove('hidden');$('resultTitle').textContent=redWins===blueWins?'DRAW — WHAT A FIGHT':redWins>blueWins?'RED CORNER WINS':'BLUE CORNER WINS';$('resultCopy').textContent=ko?'A decisive finish under the lights.':`${redWins}–${blueWins} on the judges’ cards.`;return}
    ui.overlay.classList.remove('hidden');ui.overlay.querySelector('.eyebrow').textContent='BETWEEN ROUNDS';ui.overlay.querySelector('h1').innerHTML=label.replace(' TAKES ROUND '+round,'<br><em>TAKES IT.</em>').replace(' IS A DRAW','<br><em>EVEN.</em>');ui.overlay.querySelector('p').textContent='Catch your breath. The next round is waiting.';$('startButton').textContent='START ROUND '+(round+1)+' →';$('startButton').onclick=()=>{round++;startRound();$('startButton').onclick=()=>beginMatch()};
  }
  function updateWins(){$('redWins').textContent=String(redWins).padStart(2,'0');$('blueWins').textContent=String(blueWins).padStart(2,'0');ui.round.textContent=`ROUND ${round} OF 3`;const pips=document.querySelectorAll('.clock-pips i');pips.forEach((p,i)=>p.classList.toggle('active',i<round))}
  function updateBars(){for(const f of fighters){const pre=f.side;$(pre+'Health').style.width=f.hp+'%';$(pre+'Stamina').style.width=f.stamina+'%';$(pre+'HealthText').textContent=Math.ceil(f.hp);$(pre+'StaminaText').textContent=Math.ceil(f.stamina);const condition=f.stun?'ROCKED':f.dodge==='roll'?'ROLLING':f.dodge==='slip'?'SLIPPING':f.guard?'COVERED':f.stamina<20?'GASSED':'READY';$(pre+'Condition').textContent=condition}}

  function draw(){ctx.clearRect(0,0,W,H);drawArena();const order=[...fighters].sort((a,b)=>a.depth-b.depth);for(const f of order)drawFighter(f);drawParticles();if(phase==='count'){ctx.fillStyle='#fff';ctx.textAlign='center';ctx.font=`900 ${Math.min(72,W*.12)}px Barlow Condensed, sans-serif`;ctx.shadowColor='#000';ctx.shadowBlur=18;ctx.fillText(phaseTime>2?'3':phaseTime>1?'2':'1',W/2,H*.28);ctx.shadowBlur=0}if(shake>0){/* shake is applied to impact effects only */}}
  function drawArena(){
    const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#26262b');sky.addColorStop(.47,'#151519');sky.addColorStop(1,'#08090c');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    // distant crowd and arena lamps
    for(let i=0;i<60;i++){let x=(i/60)*W;let y=H*.25+Math.sin(i*3.1)*H*.018;ctx.fillStyle=i%4===0?'#d7bd8a20':'#d9d9e012';ctx.beginPath();ctx.arc(x,y,1+(i%3)*.4,0,Math.PI*2);ctx.fill()}
    const lamp=(x,y)=>{const g=ctx.createRadialGradient(x,y,0,x,y,45);g.addColorStop(0,'#ffe7b326');g.addColorStop(1,'#ffe7b300');ctx.fillStyle=g;ctx.fillRect(x-45,y-45,90,90);ctx.fillStyle='#fff4d8';ctx.fillRect(x-8,y-2,16,3)};lamp(W*.15,H*.12);lamp(W*.85,H*.12);
    // ring canvas perspective
    const cx=W*.5;const farY=H*.35;const nearY=H*.81;ctx.fillStyle='#26272b';ctx.beginPath();ctx.moveTo(W*.10,farY);ctx.lineTo(W*.90,farY);ctx.lineTo(W*.98,nearY);ctx.lineTo(W*.02,nearY);ctx.closePath();ctx.fill();
    const mat=ctx.createLinearGradient(0,farY,0,nearY);mat.addColorStop(0,'#bbb9ad');mat.addColorStop(.35,'#9b9b95');mat.addColorStop(1,'#777a78');ctx.fillStyle=mat;ctx.beginPath();ctx.moveTo(W*.11,farY);ctx.lineTo(W*.89,farY);ctx.lineTo(W*.96,nearY);ctx.lineTo(W*.04,nearY);ctx.closePath();ctx.fill();
    // canvas graphics and seams
    ctx.save();ctx.globalAlpha=.12;ctx.strokeStyle='#24252a';ctx.lineWidth=1;for(let i=0;i<10;i++){let x=W*(.14+i*.08);ctx.beginPath();ctx.moveTo(x,farY);ctx.lineTo(cx+(x-cx)*1.12,nearY);ctx.stroke()}ctx.restore();ctx.strokeStyle='#d8d5c7';ctx.lineWidth=2;ctx.strokeRect(W*.25,H*.48,W*.50,H*.23);
    ctx.save();ctx.globalAlpha=.15;ctx.fillStyle='#24252a';ctx.font=`800 ${H*.07}px Barlow Condensed`;ctx.textAlign='center';ctx.fillText('RINGCRAFT',cx,H*.65);ctx.restore();
    // ropes, converging with perspective
    for(let i=0;i<4;i++){const y=H*(.39+i*.075),endY=H*(.39+i*.075);ctx.strokeStyle=i===1?'#e94d49':'#e5e2d7';ctx.globalAlpha=.8;ctx.lineWidth=2+i*.4;ctx.beginPath();ctx.moveTo(W*.035,y+H*.05);ctx.quadraticCurveTo(cx,y-H*.02,W*.965,y+H*.05);ctx.stroke();ctx.globalAlpha=1}
    // posts
