(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { timer: $('timer'), round: $('roundLabel'), overlay: $('centerMessage'), result: $('resultOverlay'), callout: $('callout') };
  const keys = new Set();
  let W = 0, H = 0, last = 0, running = false, phase = 'intro', phaseTime = 0, round = 1, seconds = 60, soundOn = true, audio;
  let redWins = 0, blueWins = 0, particles = [], shake = 0, callTimer = 0, totalTime = 0, clinch = null;
  const fighters = [];
  const createFighter = (name, side) => ({name, side, face: side === 'red' ? 1 : -1, x: side === 'red' ? .29 : .71, depth: side === 'red' ? .57 : .43, head: 100, body: 100, stamina: 100, stun: 0, attack: null, dodge: '', dodgeTime: 0, guard: false, hitFlash: 0, bob: 0, wins: 0, roundDamage: 0, movement: 0, actionLock: 0});
  fighters.push(createFighter('RED','red'), createFighter('BLUE','blue'));
  const config = {
    red: { left:'a', right:'d', up:'w', down:'s', slipL:'q', slipR:'e', guard:'f', roll:'g', jab:'j', hook:'k', upper:'l', body:'h', clinch:'c' },
    blue: { left:'arrowleft', right:'arrowright', up:'arrowup', down:'arrowdown', slipL:',', slipR:'.', guard:'i', roll:'o', jab:'1', hook:'2', upper:'3', body:'4', clinch:'5' }
  };
  function resize(){const r=canvas.getBoundingClientRect();const d=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0)}
  new ResizeObserver(resize).observe(canvas); resize();
  function keyName(e){return e.key.toLowerCase()}
  window.addEventListener('keydown',e=>{const k=keyName(e);if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!keys.has(k)){keys.add(k);onPress(k)} });
  window.addEventListener('keyup',e=>keys.delete(keyName(e)));
  window.addEventListener('blur',()=>keys.clear());
  $('startButton').onclick=()=>beginMatch(); $('rematchButton').onclick=()=>{redWins=blueWins=0;updateWins();beginMatch()};
  $('soundToggle').onclick=()=>{soundOn=!soundOn;$('soundLabel').textContent=soundOn?'SOUND ON':'SOUND OFF';$('soundToggle').style.color=soundOn?'#e4bd70':''};
  function onPress(k){
    if(k==='escape'&&running){running=false;phase='paused';ui.overlay.classList.remove('hidden');ui.overlay.querySelector('.eyebrow').textContent='PAUSED';ui.overlay.querySelector('h1').innerHTML='TAKE A<br><em>BREATHER.</em>';ui.overlay.querySelector('p').textContent='Press ENTER to get back in the fight.';$('startButton').textContent='BACK TO THE FIGHT →';return}
    if(k==='enter'&&phase==='paused'){running=true;phase='fight';ui.overlay.classList.add('hidden');last=performance.now();return}
    if(!running)return;
    for(const f of fighters){const c=config[f.side];if(k===c.jab)strike(f,'jab');if(k===c.hook)strike(f,'hook');if(k===c.upper)strike(f,'upper');if(k===c.body)strike(f,'body');if(k===c.clinch)startClinch(f)}
  }
  function beginMatch(){for(const f of fighters){f.head=100;f.body=100;f.stamina=100;f.stun=0;f.attack=null;f.dodge='';f.wins=0;f.roundDamage=0;f.actionLock=0}clinch=null;round=1;redWins=blueWins=0;updateWins();startRound()}
  function startRound(){seconds=60;clinch=null;for(const f of fighters){f.head=100;f.body=100;f.stamina=100;f.stun=0;f.attack=null;f.dodge='';f.guard=false;f.x=f.side==='red'?.29:.71;f.depth=f.side==='red'?.57:.43;f.roundDamage=0;f.actionLock=0}ui.result.classList.add('hidden');ui.overlay.classList.add('hidden');updateBars();running=true;phase='count';phaseTime=3;last=performance.now();}
  function strike(f,type){const costs={jab:7,hook:15,upper:17,body:10};if(clinch||f.stun>0||f.actionLock>0||f.attack||phase!=='fight'||f.stamina<costs[type])return;const data={jab:{wind:.14,active:.12,recover:.24,cost:7,damage:7,reach:.12,label:'JAB',target:'head'},hook:{wind:.24,active:.14,recover:.38,cost:15,damage:13,reach:.10,label:'HOOK',target:'head'},upper:{wind:.28,active:.12,recover:.43,cost:17,damage:16,reach:.085,label:'UPPERCUT',target:'head'},body:{wind:.19,active:.12,recover:.30,cost:10,damage:11,reach:.105,label:'BODY SHOT',target:'body'}}[type];f.stamina-=data.cost;f.attack={type,elapsed:0,hit:false,...data};f.dodge='';f.guard=false;}
  function startClinch(f){if(clinch||phase!=='fight'||f.stun>0||f.attack||f.actionLock>0)return;const other=fighters[f.side==='red'?1:0];if(Math.abs(other.x-f.x)>.19||Math.abs(other.depth-f.depth)>.13){showCall('TOO FAR TO CLINCH');return}const middle=(f.x+other.x)/2;f.x=middle-(f.side==='red'?.045:-.045);other.x=middle-(other.side==='red'?.045:-.045);const depth=(f.depth+other.depth)/2;f.depth=other.depth=depth;clinch={initiator:f.side,time:0,escape:0};for(const boxer of fighters){boxer.attack=null;boxer.guard=false;boxer.dodge='';boxer.actionLock=.25}showCall('CLINCH! MOVE TO BREAK');}
  function soundHit(strong=false){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='triangle';osc.frequency.setValueAtTime(strong?110:170,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(45,audio.currentTime+.12);gain.gain.setValueAtTime(.12,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.14);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.15)}catch{}}
  function showCall(text){ui.callout.textContent=text;ui.callout.classList.add('show');callTimer=.8}
  function attackUpdate(f,dt){if(!f.attack)return;const a=f.attack;a.elapsed+=dt;if(!a.hit&&a.elapsed>=a.wind&&a.elapsed<=a.wind+a.active){a.hit=true;const target=fighters[f.side==='red'?1:0];const dx=Math.abs(target.x-f.x);const reach=a.reach*(H/390);const depthOk=Math.abs(target.depth-f.depth)<.30;if(dx<reach+.06&&depthOk){resolveHit(f,target,a)}else if(Math.random()<.28)showCall('JUST OUT OF RANGE');}if(a.elapsed>a.wind+a.active+a.recover){f.attack=null;f.actionLock=.08}}
  function resolveHit(attacker,target,a){
    const kind=a.type, avoided=(kind==='hook'&&target.dodge==='roll')||((kind==='jab'||kind==='upper'||kind==='body')&&target.dodge==='slip');
    if(avoided){target.stamina=Math.max(0,target.stamina-2);showCall(kind==='hook'?'ROLLED UNDER!':'SLIPPED!');spawnText(target.x*W,H*(.49-target.depth*.03),kind==='hook'?'ROLL':'SLIP',target.side);attacker.actionLock=.18;return}
    let damage=a.damage;let text=a.label+'!';
    if(target.guard){damage*=a.target==='body'?.55:kind==='upper'?.55:.30;target.stamina=Math.max(0,target.stamina-(kind==='hook'?11:7));text='BLOCKED';if(target.stamina<=0){target.stun=.38;target.guard=false}}
    else{target.stun=a.target==='body'?.20:kind==='jab'?.22:.34;target.hitFlash=.18;target.x+=attacker.face*.018;}
    target[a.target]=Math.max(0,target[a.target]-damage);target.roundDamage+=damage;attacker.stamina=Math.min(100,attacker.stamina+2);shake=Math.max(shake,kind==='upper'?5:kind==='hook'?4:2);soundHit(kind!=='jab');showCall(text);spawnText(target.x*W,H*(.52-target.depth*.04),Math.round(damage)+'',target.side);updateBars();
    if(target.head<=0||target.body<=0){endRound(attacker.side==='red'?'red':'blue',true)}
  }
  function spawnText(x,y,text,side){particles.push({x,y,text,side,life:.8})}
  function update(dt){totalTime+=dt;if(callTimer>0){callTimer-=dt;if(callTimer<=0)ui.callout.classList.remove('show')}
    if(phase==='count'){phaseTime-=dt;if(phaseTime<=0){phase='fight';seconds=60;showCall('FIGHT!')}return}
    if(phase!=='fight')return;
    seconds-=dt;if(seconds<=0){seconds=0;const score=f=>f.head+f.body;endRound(score(fighters[0])===score(fighters[1])?null:score(fighters[0])>score(fighters[1])?'red':'blue',false);return}
    for(const f of fighters){const c=config[f.side],enemy=fighters[f.side==='red'?1:0];f.bob+=dt*7;f.face=enemy.x>=f.x?1:-1;f.stun=Math.max(0,f.stun-dt);f.hitFlash=Math.max(0,f.hitFlash-dt);f.actionLock=Math.max(0,f.actionLock-dt);f.dodgeTime=Math.max(0,f.dodgeTime-dt);if(f.dodgeTime<=0)f.dodge='';
      f.guard=!clinch&&keys.has(c.guard)&&f.stun<=0&&!f.attack;if(f.guard)f.stamina=Math.max(0,f.stamina-dt*9);else f.stamina=Math.min(100,f.stamina+dt*(f.attack?3:12));if(f.stamina<=0)f.guard=false;
      if(!clinch&&f.dodgeTime<=0&&f.actionLock<=0&&f.stun<=0&&!f.attack){if(keys.has(c.slipL)){f.dodge='slip';f.dodgeTime=.18;f.actionLock=.18;f.x-=f.face*.018;f.stamina=Math.max(0,f.stamina-5)}else if(keys.has(c.slipR)){f.dodge='slip';f.dodgeTime=.18;f.actionLock=.18;f.x+=f.face*.018;f.stamina=Math.max(0,f.stamina-5)}else if(keys.has(c.roll)){f.dodge='roll';f.dodgeTime=.39;f.actionLock=.39;f.stamina=Math.max(0,f.stamina-12)}}
      f.movement=0;if(!clinch&&f.stun<=0&&!f.attack&&!f.dodge){const dx=(keys.has(c.right)?1:0)-(keys.has(c.left)?1:0),dy=(keys.has(c.down)?1:0)-(keys.has(c.up)?1:0),length=Math.hypot(dx,dy)||1;if(dx||dy){f.x+=dx/length*dt*.25;f.depth+=dy/length*dt*.19;f.movement=dx||dy}}
      const minX=.12-Math.max(0,f.depth-.38)*.25,maxX=1-minX;f.x=Math.max(minX,Math.min(maxX,f.x));f.depth=Math.max(.38,Math.min(.68,f.depth));attackUpdate(f,dt);
    }
    if(clinch){clinch.time+=dt;let effort=0;for(const f of fighters){const c=config[f.side];if(keys.has(c.left)||keys.has(c.right)||keys.has(c.up)||keys.has(c.down))effort+=1}clinch.escape+=effort*dt;if(clinch.escape>.65||clinch.time>1.8){clinch=null;for(const f of fighters)f.actionLock=Math.max(f.actionLock,.25);showCall('BREAK!');}}
    else{const [red,blue]=fighters,dx=blue.x-red.x;if(dx<.16&&Math.abs(blue.depth-red.depth)<.11){const push=(.16-dx)*.5;red.x-=push;blue.x+=push}}
    particles=particles.filter(p=>{p.life-=dt;p.y-=dt*22;return p.life>0});shake=Math.max(0,shake-dt*22);updateBars();
  }
  function endRound(winner,ko){if(phase!=='fight')return;running=false;phase='between';if(winner==='red')redWins++;if(winner==='blue')blueWins++;updateWins();const label=winner?`${winner==='red'?'RED':'BLUE'} CORNER TAKES ROUND ${round}`:'ROUND '+round+' IS A DRAW';showCall(ko?'KNOCKDOWN!':'BELL!');
    if(redWins>=2||blueWins>=2||round>=3){phase='result';ui.result.classList.remove('hidden');$('resultTitle').textContent=redWins===blueWins?'DRAW — WHAT A FIGHT':redWins>blueWins?'RED CORNER WINS':'BLUE CORNER WINS';$('resultCopy').textContent=ko?'A decisive finish under the lights.':`${redWins}–${blueWins} on the judges’ cards.`;return}
    ui.overlay.classList.remove('hidden');ui.overlay.querySelector('.eyebrow').textContent='BETWEEN ROUNDS';ui.overlay.querySelector('h1').innerHTML=label.replace(' TAKES ROUND '+round,'<br><em>TAKES IT.</em>').replace(' IS A DRAW','<br><em>EVEN.</em>');ui.overlay.querySelector('p').textContent='Catch your breath. The next round is waiting.';$('startButton').textContent='START ROUND '+(round+1)+' →';$('startButton').onclick=()=>{round++;startRound();$('startButton').onclick=()=>beginMatch()};
  }
