const drawArm=(arm,punch,guarding)=>{
  const lead=arm==='lead',sx=lead?17:-9,sy=lead?-121:-119,ex=lead?31:-1,ey=lead?-118:-101,fx=lead?43:23,fy=lead?-112:-115;
  let reach=0,punchY=fy,elbowY=ey,curve=0,angle=.05;
  if(guarding){reach=lead?-7:-2;punchY=lead?-121:-115}
  if(punch){
    const a=punch,t=a.elapsed,wind=Math.min(1,t/a.wind),activeEnd=a.wind+a.active,full=a.style==='straight'?(lead?45:50):a.style==='hook'?34:27;
    if(t<a.wind){const ease=Math.sin(wind*Math.PI/2);reach=(a.arm==='rear'?-12:-5)*(1-ease)+full*.08*ease}
    else if(t<activeEnd)reach=full;
    else reach=full*Math.max(0,1-(t-activeEnd)/a.recover);
    if(a.style==='hook'){curve=lead?13:19;angle=lead?-.34:.34;punchY=a.target==='body'?-79:-118;elbowY=a.target==='body'?-92:-119}
    else if(a.style==='uppercut'){punchY=a.target==='body'?-80:-126;elbowY=a.target==='body'?-94:-118;reach=reach*.58;curve=-9}
    else{punchY=a.target==='body'?-79:-112;elbowY=(ey+punchY)*.48;}
    if(t<a.wind&&a.style==='uppercut'){punchY+=18*wind;elbowY+=9*wind}
  }
  const startX=sx+(lead?0:5), gloveX=fx+reach, elbowX=ex+reach*(punch?.52:.35);
  ctx.strokeStyle=skin(f.side);ctx.lineWidth=12;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(startX,sy+bob);
  if(punch?.style==='hook'){ctx.quadraticCurveTo(elbowX+curve,elbowY-curve*.35+bob,gloveX,punchY+bob)}
  else{ctx.lineTo(elbowX,elbowY+bob);ctx.lineTo(gloveX,punchY+bob)}ctx.stroke();
  ctx.fillStyle=glove;ctx.beginPath();ctx.ellipse(gloveX,punchY+bob,13,11,angle,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#ffffff55';roundRect(ctx,gloveX-8,punchY-3+bob,15,3,2);ctx.fill();ctx.strokeStyle='#ffffff44';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(gloveX-5,punchY+3+bob);ctx.lineTo(gloveX+6,punchY+3+bob);ctx.stroke();
};
const punchingArm=f.attack?.arm;const otherArm=punchingArm==='lead'?'rear':'lead';
drawArm(otherArm,null,f.guard&&!f.attack);drawArm(punchingArm||'lead',f.attack,f.guard&&!f.attack);

