*{
box-sizing:border-box}
body{
margin:0;background:var(--bg);color:var(--white);font-family:Manrope,Arial,sans-serif;min-height:100vh;background-image:radial-gradient(ellipse at 50% -30%,#27252b 0,transparent 58%)}
button{
