.brand-mark{
width:26px;height:26px;border:1px solid var(--gold);color:var(--gold);display:grid;place-items:center;font-size:16px}
.brand-light{
font-weight:500;color:#999}
.event,.sound-button{
font:10px 'DM Mono',monospace;letter-spacing:1.2px;color:#a6a6aa}
.event{
display:flex;gap:10px;align-items:center}
.live-dot{
height:6px;width:6px;border-radius:50%;background:var(--red);box-shadow:0 0 10px #ee4d4a}
