border:1px solid #37383d;background:transparent;color:#aaa;padding:9px 12px;display:flex;align-items:center;gap:8px;cursor:pointer}
.sound-button:hover{
border-color:var(--gold);color:var(--gold)}
.sound-icon{
font-size:15px}
.fight-card{
display:flex;justify-content:space-between;align-items:center;padding:22px 4px 19px}
.fighter-head{
display:flex;align-items:center;gap:30px;width:40%}
.blue-head{
justify-content:flex-end;text-align:right}
.fighter-id h2{
font:800 32px/.82 'Barlow Condensed',sans-serif;letter-spacing:.3px;margin:8px 0 7px}
.fighter-id em{
font-style:normal;color:var(--red)}
.blue-head em{
color:var(--blue)}
.fighter-id p{
font:9px 'DM Mono',monospace;color:#898b92;letter-spacing:1px;margin:0}
.corner-tag,.eyebrow{
font:9px 'DM Mono',monospace;letter-spacing:1.5px;color:#aaa}
.red-tag{
color:var(--red)}
.blue-tag{
color:var(--blue)}
.record{
display:flex;flex-direction:column;align-items:center;border-left:1px solid #ffffff20;padding-left:17px}
.blue-head .record{
border-left:0;border-right:1px solid #ffffff20;padding-left:0;padding-right:17px}
.record strong{
font:700 21px 'Barlow Condensed',sans-serif}
.record span{
font:8px 'DM Mono',monospace;letter-spacing:1px;color:#6f7078}
.arena-wrap{
border:1px solid #393a40;background:#111216;box-shadow:0 18px 55px #0005}
.arena-topline,.arena-bottomline{
height:31px;display:flex;align-items:center;justify-content:space-between;padding:0 14px;font:9px 'DM Mono',monospace;letter-spacing:1px;color:#85868c}
.arena-topline{
border-bottom:1px solid #ffffff10}
.arena-bottomline{
border-top:1px solid #ffffff12}
.round-label{
color:var(--gold)}
