height:390px;position:relative;overflow:hidden;background:#17171b}
.canvas-frame canvas{
width:100%;height:100%;display:block}
.round-clock{
position:absolute;top:15px;left:50%;transform:translateX(-50%);z-index:2;display:flex;align-items:center;gap:11px;background:#0c0d0fdb;border:1px solid #ffffff1a;padding:7px 12px}
.clock-label{
font:8px 'DM Mono',monospace;color:#8b8b91;letter-spacing:.8px}
