font:700 17px 'Barlow Condensed',sans-serif;min-width:30px;text-align:center}
.clock-pips{
display:flex;gap:3px}
.clock-pips i{
width:5px;height:5px;border-radius:50%;background:#51525a}
.clock-pips i.active{
background:var(--gold)}
.callout{
position:absolute;top:77px;left:50%;transform:translateX(-50%);z-index:2;font:800 22px 'Barlow Condensed',sans-serif;font-style:italic;letter-spacing:2px;color:var(--gold);text-shadow:0 2px 12px #000;opacity:0;transition:opacity .15s;white-space:nowrap}
.callout.show{
opacity:1}
.center-message,.result-overlay{
position:absolute;inset:0;z-index:3;display:grid;place-items:center;background:linear-gradient(90deg,#090a0dce,#111216a8 50%,#090a0dce)}
.message-card{
text-align:center;max-width:450px;padding:22px}
.message-card h1{
font:900 57px/.82 'Barlow Condensed',sans-serif;letter-spacing:1px;margin:13px 0}
.message-card h1 em{
font-style:normal;color:var(--gold)}
.message-card p,.result-overlay p{
font-size:11px;color:#aaa;letter-spacing:.3px;margin:12px 0 20px}
.start-button{
