.start-button span{
font-size:17px;margin-left:12px}
.start-button:hover{
transform:translateY(-2px);background:#f2d18a}
.quick-hint{
margin-top:16px;font:8px 'DM Mono',monospace;color:#999;letter-spacing:.6px}
.quick-hint kbd{
margin:0 3px}
.result-overlay{
text-align:center;align-content:center}
.result-overlay h2{
font:900 40px 'Barlow Condensed',sans-serif;margin:12px 0;color:var(--gold)}
.hidden{
display:none!important}
.status-row{
display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:13px 0 22px}
.status-box{
background:#17181d;border:1px solid #292a30;padding:12px 15px}
.status-title,.meter-label{
display:flex;justify-content:space-between;align-items:center}
.status-title{
font:9px 'DM Mono',monospace;letter-spacing:1px;color:var(--red);margin-bottom:10px}
.blue-status .status-title{
color:var(--blue)}
.status-title span+span{
font-size:8px;color:#85858b}
.meter-label{
font:8px 'DM Mono',monospace;color:#777981;letter-spacing:.7px;margin:5px 0}
.meter-label strong{
font-weight:400;color:#ccc}
.meter{
height:5px;background:#2c2d33;overflow:hidden}
.meter i{
height:100%;width:100%;display:block;transition:width .18s}
.health i{
background:linear-gradient(90deg,#df4945,#f88673)}
.blue-status .health i{
background:linear-gradient(90deg,#3a80bf,#68c6e8)}
.stamina i{
background:var(--gold)}
.stamina-label{
margin-top:8px}
.controls{
border-top:1px solid #ffffff13;border-bottom:1px solid #ffffff13}
.controls-heading{
display:flex;justify-content:space-between;padding:11px 1px;border-bottom:1px solid #ffffff12;font:9px 'DM Mono',monospace;letter-spacing:1.2px;color:#82838a}
.controls-heading span:last-child{
color:#5d5e66}
.control-columns{
display:grid;grid-template-columns:1fr 1fr}
.control-player{
display:flex;gap:13px;padding:15px 9px;border-right:1px solid #ffffff12}
.control-player:last-child{
border:0;padding-left:20px}
.player-number{
font:800 23px 'Barlow Condensed',sans-serif}
.red-text{
color:var(--red)}
.blue-text{
color:var(--blue)}
.control-info h3{
margin:1px 0 10px;font:700 10px 'DM Mono',monospace;letter-spacing:1px}
.key-grid{
display:grid;grid-template-columns:1fr 1fr;gap:7px 17px}
.key-grid span{
font:8px 'DM Mono',monospace;color:#95969c;white-space:nowrap;display:flex;align-items:center;gap:4px}
.key-grid kbd,.quick-hint kbd{
min-width:18px;height:18px;padding:0 4px;display:inline-grid;place-items:center;border:1px solid #44454b;border-bottom-width:2px;border-radius:2px;color:#dedee0;font:9px 'DM Mono',monospace}
.tip{
font:9px 'DM Mono',monospace;color:#8c8d93;padding:0 0 13px;margin:0;letter-spacing:.1px}
.tip span{
color:var(--gold);margin-right:9px}
footer{
display:flex;justify-content:space-between;color:#5f6068;font:8px 'DM Mono',monospace;letter-spacing:1px;padding-top:17px}
footer i{
font-style:normal;color:var(--gold);padding:0 3px}

